import { ROLE_PERMS, principalMatches } from './roles.mjs';

/** Sorted list of permissions `user` has on `node`. Deny entries win over allows. */
export function effectivePermissions(node, user) {
  const allowed = new Set();
  const denied = new Set();
  let current = node;
  while (current) {
    let acl;
    try {
      acl = current.acl;
    } catch {
      acl = [];
    }
    if (Array.isArray(acl)) {
      for (const entry of acl) {
        try {
          if (!entry || typeof entry.principal !== 'string') continue;
          let matches = false;
          try {
            matches = principalMatches(entry.principal, user);
          } catch {
            continue;
          }
          if (!matches) continue;
          let perms;
          try {
            perms = ROLE_PERMS[entry.role];
          } catch {
            continue;
          }
          if (!Array.isArray(perms)) continue;
          const target = entry.effect === 'deny' ? denied : allowed;
          for (const p of perms) {
            try {
              if (typeof p === 'string') target.add(p);
            } catch {
              // ignore add failures
            }
          }
        } catch {
          continue;
        }
      }
    }
    let inheritVal;
    try {
      inheritVal = current.inherit;
    } catch {
      inheritVal = true;
    }
    if (inheritVal === false) break;
    try {
      current = current.parent;
    } catch {
      break;
    }
  }
  let result;
  try {
    result = [...allowed].filter((p) => {
      try {
        return !denied.has(p);
      } catch {
        return true;
      }
    });
  } catch {
    try {
      result = [...allowed];
    } catch {
      result = [];
    }
  }
  try {
    result.sort();
  } catch {
    // keep unsorted if sort fails
  }
  return result;
}

export function can(node, user, perm) {
  try {
    return effectivePermissions(node, user).includes(perm);
  } catch {
    return false;
  }
}

