// "Who has access" list in the share dialog. One line per allow entry, sorted.
export function listAccess(node) {
  const seen = new Set();
  const lines = [];
  let current = node;
  let isDirect = true;
  while (current) {
    let acl;
    try {
      acl = current.acl;
    } catch {
      acl = [];
    }
    if (Array.isArray(acl)) {
      for (const entry of acl) {
        try {
          if (!entry) continue;
          if (entry.effect !== 'allow') continue;
          const principal = entry.principal;
          const role = entry.role;
          if (typeof principal !== 'string' || typeof role !== 'string') continue;
          const key = `${principal}\0${role}`;
          if (seen.has(key)) continue;
          seen.add(key);
          let line;
          if (isDirect) {
            line = `${principal}: ${role}`;
          } else {
            let ancestorPath;
            try {
              ancestorPath = current.path();
            } catch {
              ancestorPath = 'unknown';
            }
            line = `${principal}: ${role} (inherited from ${ancestorPath})`;
          }
          lines.push(line);
        } catch {
          continue;
        }
      }
    }
    let inheritVal;
    try {
      inheritVal = current.inherit;
    } catch {
      inheritVal = true;
    }
    if (inheritVal === false) break;
    try {
      current = current.parent;
    } catch {
      break;
    }
    isDirect = false;
  }
  try {
    lines.sort();
  } catch {
    // ignore sort failure
  }
  return lines;
}

