/**
 * Acquire a connection, run fn(conn, scope), then clean up.
 * Callbacks deferred on `scope` by fn run before the connection is released.
 */
export async function withConnection(pool, fn) {
  let conn;
  try {
    conn = await pool.acquire();
  } catch (e) {
    throw e;
  }

  const scope = new Scope();
  try {
    scope.defer(() => pool.release(conn));
  } catch (deferErr) {
    try {
      pool.release(conn);
    } catch (_) {
      // suppress release error, keep original defer error
    }
    throw deferErr;
  }

  let fnResult;
  let fnError = null;
  let fnSucceeded = false;

  try {
    const maybe = fn(conn, scope);
    fnResult = await maybe;
    fnSucceeded = true;
  } catch (e) {
    fnError = e;
    fnSucceeded = false;
  }

  let closeError = null;
  try {
    await scope.close();
  } catch (e) {
    closeError = e;
  }

  if (!fnSucceeded) {
    throw fnError;
  }
  if (closeError) {
    throw closeError;
  }
  return fnResult;
}

