import { MinHeap } from './heap.mjs';

// Cooperative job scheduler driven by tick(). Uses an injected clock.
// Log entries: { t, name, status: 'ok' } or { t, name, status: 'error', message }
export class Scheduler {
  constructor({ now = () => Date.now() } = {}) {
    this.now = now;
    this.seq = 0;
    // earliest runAt first; seq breaks ties so equal-time jobs run in submission order
    // priority is handled after collecting due jobs, so heap stays ordered by time
    this.heap = new MinHeap((a, b) => a.runAt - b.runAt || a.seq - b.seq);
    this.pending = new Set();
    this.log = [];
  }

  schedule(name, fn, { delayMs = 0, priority = 5 } = {}) {
    if (typeof fn !== 'function') throw new TypeError('job must be a function');
    if (typeof priority !== 'number' || !Number.isInteger(priority) || priority < 0 || priority > 9) {
      throw new RangeError('priority must be an integer between 0 and 9');
    }
    let runAt;
    try {
      const nowVal = this.now();
      // now() is expected sync; if it returns a Promise we treat runAt as invalid and let it throw later,
      // but we defensively avoid scheduling with NaN by checking type
      if (nowVal instanceof Promise) {
        // If clock is async, we cannot compute runAt synchronously; propagate as error to avoid corrupt heap
        throw new TypeError('clock must be synchronous');
      }
      runAt = nowVal + delayMs;
    } catch (err) {
      throw err;
    }
    const seq = ++this.seq;
    const job = { id: seq, seq, name, fn, runAt, priority };
    try {
      this.heap.push(job);
    } catch (err) {
      throw err;
    }
    try {
      this.pending.add(job.id);
    } catch (err) {
      // heap contains job but pending does not, so it will be ignored on tick (failure isolation)
      throw err;
    }
    return job.id;
  }

  /** Cancel a job that has not started yet. Returns true if it was pending. */
  cancel(id) {
    return this.pending.delete(id);
  }

  /**
   * Run every job that is due now. Jobs scheduled while this tick runs wait for a later tick.
   * Returns the number of jobs run.
   */
  async tick() {
    let t;
    try {
      const maybe = this.now();
      t = maybe instanceof Promise ? await maybe : maybe;
    } catch (err) {
      throw err;
    }

    const due = [];
    try {
      while (this.heap.size) {
        let peeked;
        try {
          peeked = this.heap.peek();
        } catch (_) {
          break;
        }
        if (!peeked || peeked.runAt > t) break;
        let job;
        try {
          job = this.heap.pop();
        } catch (_) {
          break;
        }
        if (!job) break;
        let isPending = false;
        try {
          isPending = this.pending.has(job.id);
          if (isPending) this.pending.delete(job.id);
        } catch (_) {
          continue;
        }
        if (isPending) due.push(job);
      }
    } catch (_) {
      // continue with whatever due jobs we collected
    }

    try {
      due.sort((a, b) => {
        const d = b.priority - a.priority;
        if (d !== 0) return d;
        return a.seq - b.seq;
      });
    } catch (_) {
      // keep original order if sort fails
    }

    for (const job of due) {
      try {
        let result;
        try {
          result = job.fn();
        } catch (err) {
          throw err;
        }
        try {
          await result;
        } catch (err) {
          throw err;
        }
        try {
          this.log.push({ t, name: job.name, status: 'ok' });
        } catch (_) {}
      } catch (err) {
        try {
          const message = err && typeof err.message === 'string' ? err.message : String(err);
          this.log.push({ t, name: job.name, status: 'error', message });
        } catch (_) {
          try {
            this.log.push({ t, name: job.name, status: 'error', message: 'unknown' });
          } catch (_) {}
        }
      }
    }
    return due.length;
  }
}

