// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map(); // seq -> event
    this._bufferedIds = new Set();
    this._appliedIds = new Set();
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    // Defensive validation - malformed events are ignored
    if (!event || (typeof event.id !== 'string' && typeof event.id !== 'number') || typeof event.seq !== 'number') {
      return [];
    }

    // Idempotency by id: already applied or already buffered
    if (this._appliedIds.has(event.id) || this._bufferedIds.has(event.id)) {
      return [];
    }

    // Stale seq: already applied (lastSeq is contiguous high-water mark)
    if (event.seq <= this.lastSeq) {
      return [];
    }

    // Duplicate seq already buffered with different id - ignore to keep first
    if (this._buffer.has(event.seq)) {
      return [];
    }

    // Buffer the event
    this._buffer.set(event.seq, event);
    this._bufferedIds.add(event.id);

    const applied = [];

    try {
      while (true) {
        const nextSeq = this.lastSeq + 1;
        const nextEvent = this._buffer.get(nextSeq);
        if (!nextEvent) break;

        let result;
        try {
          result = this.apply(nextEvent);
        } catch (syncErr) {
          // Failure isolation: do not advance, keep buffered for retry, propagate
          throw syncErr;
        }

        // Untrusted invocation: handle thenable without assuming well-formed async
        if (result && typeof result.then === 'function') {
          try {
            result.then(
              () => {
                // Async success path - only apply if still the buffered event for that seq
                if (this._buffer.has(nextSeq) && this._buffer.get(nextSeq).id === nextEvent.id) {
                  this._buffer.delete(nextSeq);
                  this._bufferedIds.delete(nextEvent.id);
                  this._appliedIds.add(nextEvent.id);
                  this.lastSeq = nextSeq;
                  // Continue draining synchronously for any further buffered events
                  let cur = this.lastSeq + 1;
                  while (this._buffer.has(cur)) {
                    const ev = this._buffer.get(cur);
                    try {
                      const r = this.apply(ev);
                      if (r && typeof r.then === 'function') {
                        if (typeof r.catch === 'function') r.catch(() => {});
                        break;
                      }
                      this._buffer.delete(cur);
                      this._bufferedIds.delete(ev.id);
                      this._appliedIds.add(ev.id);
                      this.lastSeq = cur;
                      cur++;
                    } catch (_) {
                      break;
                    }
                  }
                }
              },
              () => {
                // Async rejection - keep buffered, failure not persisted as success
              }
            );
            if (typeof result.catch === 'function') {
              result.catch(() => {});
            }
          } catch (_) {
            // Attaching handlers threw - treat as async in-flight, keep buffered
          }
          // Break sync drain; async completion will continue later
          break;
        }

        // Sync success - guaranteed cleanup via finally-style state update
        this._buffer.delete(nextSeq);
        this._bufferedIds.delete(nextEvent.id);
        this._appliedIds.add(nextEvent.id);
        this.lastSeq = nextSeq;
        applied.push(nextEvent);
      }
    } catch (err) {
      // Ensure no stale success markers; buffer still holds failed event
      throw err;
    } finally {
      // pendingCount reflects _buffer.size; no resources to release
    }

    return applied;
  }
}

