import { resolveDialect } from './dialects.mjs';

function needsQuoting(s, d) {
  return s.includes(d.delimiter) || s.includes(d.quote) || s.includes('\r') || s.includes('\n');
}

/** rows: any[][] -> CSV text (always ends with a line terminator). null/undefined -> empty field. */
export function stringify(rows, opts = {}) {
  const d = resolveDialect(opts);
  const cell = (v) => {
    let s;
    if (v == null) s = '';
    else if (typeof v === 'number') {
      s = String(v);
      if (d.decimal !== '.' && s.includes('.')) {
        s = s.replace('.', d.decimal);
      }
    } else {
      s = String(v);
    }
    return needsQuoting(s, d) ? d.quote + s.split(d.quote).join(d.quote + d.quote) + d.quote : s;
  };
  return rows.map((r) => r.map(cell).join(d.delimiter)).join(d.lineTerminator) + d.lineTerminator;
}

/**
 * CSV text -> string[][]. Accepts CRLF or LF line endings. Quoted fields may contain
 * commas, doubled quotes and newlines. A trailing newline does not produce an empty row.
 */
export function parse(text, opts = {}) {
  const d = resolveDialect(opts);
  const delimiter = d.delimiter;
  const quote = d.quote;
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let i = 0;
  while (i < text.length) {
    if (inQuotes) {
      if (text.startsWith(quote, i)) {
        if (text.startsWith(quote, i + quote.length)) {
          field += quote;
          i += quote.length * 2;
          continue;
        } else {
          inQuotes = false;
          i += quote.length;
          continue;
        }
      }
      field += text[i];
      i++;
      continue;
    }
    if (field === '' && text.startsWith(quote, i)) {
      inQuotes = true;
      i += quote.length;
      continue;
    }
    if (text.startsWith(delimiter, i)) {
      row.push(field);
      field = '';
      i += delimiter.length;
      continue;
    }
    if (text[i] === '\r' && text[i + 1] === '\n') {
      i++;
      continue;
    }
    if (text[i] === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      i++;
      continue;
    }
    field += text[i];
    i++;
  }
  if (field !== '' || row.length) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}

