import { parse } from './csv.mjs';
import { resolveDialect } from './dialects.mjs';

/** Bank statement CSV with a header row: date,description,amount */
export function importBankFile(text, opts = {}) {
  const d = resolveDialect(opts);
  const [header, ...rows] = parse(text, opts);
  const idx = Object.fromEntries(header.map((h, i) => [h.trim(), i]));
  return rows.map((r) => {
    let raw = r[idx.amount];
    let amountStr = raw == null ? '' : String(raw).trim();
    if (amountStr) {
      if (d.decimal === ',' && amountStr.includes(',')) {
        amountStr = amountStr.replace(/\./g, '');
        amountStr = amountStr.split(d.decimal).join('.');
      } else if (d.decimal !== '.') {
        amountStr = amountStr.split(d.decimal).join('.');
      } else if (amountStr.includes('.') && amountStr.includes(',')) {
        amountStr = amountStr.replace(/,/g, '');
      }
    }
    return {
      date: r[idx.date],
      description: r[idx.description],
      amount: Number(amountStr),
    };
  });
}
